#!/usr/bin/env python3
import json
import os
import re
import gzip
import argparse
import sys

# --- Helper Functions ---

def get_summary_data(folder_path):
    """Reads the summary.json generated by Truvari."""
    file_path = os.path.join(folder_path, "summary.json")
    if not os.path.exists(file_path):
        return {}
    try:
        with open(file_path, 'r') as f:
            return json.load(f)
    except Exception as e:
        print(f"Error reading summary.json in {folder_path}: {e}", file=sys.stderr)
        return {}

def get_deviation_data(folder_path):
    """Parses length_breakpoint_deviation.log."""
    file_path = os.path.join(folder_path, "length_breakpoint_deviation.log")
    data = {
        "Avg_abs_length_deviation": 0.0, "Median_abs_length_deviation": 0.0,
        "Avg_norm_length_deviation": 0.0, "Median_norm_length_deviation": 0.0,
        "Avg_abs_breakpoint_deviation": 0.0, "Median_abs_breakpoint_deviation": 0.0,
        "Avg_norm_breakpoint_deviation": 0.0, "Median_norm_breakpoint_deviation": 0.0
    }
    
    if not os.path.exists(file_path):
        return data

    with open(file_path, 'r') as f:
        for line in f:
            m = re.search(r':\s*(\d+\.?\d*)', line)
            if not m: continue
            try:
                value = float(m.group(1))
            except ValueError: continue

            if "Average Absolute Length Deviation" in line: data["Avg_abs_length_deviation"] = value
            elif "Median Absolute Length Deviation" in line: data["Median_abs_length_deviation"] = value
            elif "Average Normalized Length Deviation" in line: data["Avg_norm_length_deviation"] = value
            elif "Median Normalized Length Deviation" in line: data["Median_norm_length_deviation"] = value
            elif "Average Absolute Breakpoint Deviation" in line: data["Avg_abs_breakpoint_deviation"] = value
            elif "Median Absolute Breakpoint Deviation" in line: data["Median_abs_breakpoint_deviation"] = value
            elif "Average Normalized Breakpoint Deviation" in line: data["Avg_norm_breakpoint_deviation"] = value
            elif "Median Normalized Breakpoint Deviation" in line: data["Median_norm_breakpoint_deviation"] = value
    return data

def load_ids_from_vcf(vcf_path):
    """Loads variant IDs (column 3) from a gzipped VCF."""
    ids = set()
    if not os.path.exists(vcf_path):
        return ids
    try:
        with gzip.open(vcf_path, 'rt') as f:
            for line in f:
                if line.startswith('#'): continue
                fields = line.strip().split('\t')
                if len(fields) >= 3:
                    ids.add(fields[2])
    except Exception:
        pass # Silently fail/return empty set on error
    return ids

def find_result_directories(base_path, sample_name):
    """
    Scans the base_path to find the Overall, Tier1, and Tier2 directories.
    Assumes folders start with {sample_name}_.
    """
    dirs = {"Overall": None, "Tier1": None, "Tier2": None}
    
    if not os.path.exists(base_path):
        print(f"Error: Path {base_path} does not exist.")
        return dirs

    # Normalize sample name for search
    search_prefix = sample_name
    
    for entry in os.listdir(base_path):
        full_path = os.path.join(base_path, entry)
        if not os.path.isdir(full_path):
            continue
        
        # Check if directory starts with the sample name
        if entry.startswith(search_prefix):
            # Check for Tier1
            if "Tier1" in entry or "Cate1" in entry:
                dirs["Tier1"] = full_path
            # Check for Tier2
            elif "Tier2" in entry or "Cate2" in entry:
                dirs["Tier2"] = full_path
            # If it matches sample but not Tier1/2, it's likely the Overall/Merged
            elif "merged" in entry and not ("Tier" in entry or "Cate" in entry):
                dirs["Overall"] = full_path

    return dirs

def calculate_tier_stats(current_tier_name, current_dir, other_tier_dir, is_tier_calculation=False):
    """
    Calculates stats. If is_tier_calculation is True, performs the 
    Tier Specific Precision adjustment: TP / (TP + FP - (FP intersect TP_other))
    """
    results = {}
    
    # 1. Basic Truvari Summary
    summary = get_summary_data(current_dir)
    results.update(summary)
    
    # 2. Deviation Data
    deviations = get_deviation_data(current_dir)
    results.update(deviations)

    # 3. Get TP counts and paths
    tp_vcf = os.path.join(current_dir, "tp-comp.vcf.gz")
    fp_vcf = os.path.join(current_dir, "fp.vcf.gz")
    
    tp_ids = load_ids_from_vcf(tp_vcf)
    num_tp = len(tp_ids)
    results["Num_TP_comp"] = num_tp

    # 4. Tier Specific Logic
    if is_tier_calculation and other_tier_dir:
        # Load FP IDs from current tier
        fp_ids = load_ids_from_vcf(fp_vcf)
        
        # Load TP IDs from the OTHER tier
        other_tp_vcf = os.path.join(other_tier_dir, "tp-comp.vcf.gz")
        other_tp_ids = load_ids_from_vcf(other_tp_vcf)
        
        # Calculate Overlap
        overlap = len(fp_ids.intersection(other_tp_ids))
        
        # Adjusted Denominator: TP + FP - Overlap
        # Note: Standard precision is TP / (TP + FP). 
        # Here we remove the FP that are actually TP in the other tier.
        denom = num_tp + len(fp_ids) - overlap
        
        precision = num_tp / denom if denom > 0 else 0.0
        recall = summary.get("recall", 0.0) # Recall comes from Truvari summary
        
        f1 = 0.0
        if (precision + recall) > 0:
            f1 = 2 * precision * recall / (precision + recall)
            
        results[f"{current_tier_name}_Adjusted_Precision"] = precision
        results[f"{current_tier_name}_Adjusted_F1"] = f1
        results["Overlap_with_Other_Tier_TP"] = overlap
    
    return results

# --- Main Script ---

def main():
    parser = argparse.ArgumentParser(description="Calculate Tier-Specific Precision/Recall/F1 from Truvari results.")
    parser.add_argument("results_dir", help="Directory containing the output folders from the bash script")
    parser.add_argument("sample_name", help="Sample Name (e.g., HG002)")
    parser.add_argument("--output", default="tier_metrics.json", help="Output JSON filename")
    
    args = parser.parse_args()

    print(f"Searching for results in: {args.results_dir} for sample: {args.sample_name}")
    
    # 1. Locate directories
    dirs = find_result_directories(args.results_dir, args.sample_name)
    
    final_output = {
        "Sample": args.sample_name,
        "Results": {}
    }
    
    # 2. Process Overall
    if dirs["Overall"]:
        print(f"Found Overall Dir: {os.path.basename(dirs['Overall'])}")
        final_output["Results"]["Overall"] = calculate_tier_stats("Overall", dirs["Overall"], None, False)
    else:
        print("Warning: Could not find Overall/Merged directory.")

    # 3. Process Tier 1 (vs Tier 2)
    if dirs["Tier1"]:
        print(f"Found Tier 1 Dir: {os.path.basename(dirs['Tier1'])}")
        # We need Tier 2 to calculate Tier 1 adjusted precision
        final_output["Results"]["Tier1"] = calculate_tier_stats("Tier1", dirs["Tier1"], dirs["Tier2"], True)
    else:
        print("Warning: Could not find Tier 1 directory.")

    # 4. Process Tier 2 (vs Tier 1)
    if dirs["Tier2"]:
        print(f"Found Tier 2 Dir: {os.path.basename(dirs['Tier2'])}")
        # We need Tier 1 to calculate Tier 2 adjusted precision
        final_output["Results"]["Tier2"] = calculate_tier_stats("Tier2", dirs["Tier2"], dirs["Tier1"], True)
    else:
        print("Warning: Could not find Tier 2 directory.")

    # 5. Output
    print("\n--- JSON OUTPUT ---")
    json_str = json.dumps(final_output, indent=4)
    print(json_str)
    
    with open(args.output, 'w') as f:
        f.write(json_str)
    print(f"Saved results to {args.output}")

if __name__ == "__main__":
    main()
